WITH department_totals AS (SELECT dept_id, ROUND((100 * SUM(CASE WHEN level = 'L4' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l4, ROUND((100 * SUM(CASE WHEN level = 'L5' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l5 FROM employees WHERE job_title <> 'Analyst' GROUP BY dept_id) SELECT d.id, d.budget, dt.pct_l4, dt.pct_l5 FROM departments d LEFT JOIN department_totals dt ON d.id = dt.dept_id WHERE dt.pct_l5 > 58 ORDER BY dt.pct_l4 DESC;
